import { test, expect } from '@playwright/test';
import { transferHtml } from '../../../src/shared/test-page.js';

test('generated transfer regression', async ({ page }) => {
  await page.route('https://bank.test/api/v1/transfers', async route => {
    const payload = route.request().postDataJSON();
    const ok = payload?.beneficiary === 'customer.bob' && payload?.amount?.value === '100.00';
    await route.fulfill({status:ok?201:422,contentType:'application/json',body:JSON.stringify(ok?{id:'TR-P0C-001',status:'SETTLED',correlationId:'CORR-P0C'}:{status:'FAILED'})});
  });
  await page.setContent(transferHtml);
  await test.step('select beneficiary', async()=>{ await page.getByTestId('transfer-beneficiary').selectOption('customer.bob'); });
  await test.step('fill amount', async()=>{ await page.getByTestId('transfer-amount').fill('100.00'); });
  await test.step('submit', async()=>{
    const responsePromise=page.waitForResponse(r=>r.url().includes('/api/v1/transfers'));
    await page.getByTestId('transfer-confirm').click();
    expect((await responsePromise).status()).toBe(201);
  });
  await expect(page.getByTestId('transfer-status')).toHaveText('转账成功');
});
